"""The committed benchmark summary (generated by ``scam_bench.run_benchmark --json-out``)."""

from __future__ import annotations

import json
from functools import lru_cache
from importlib import resources
from typing import Any

FILE = "benchmark_summary.json"


@lru_cache(maxsize=1)
def load_summary() -> dict[str, Any]:
    raw = resources.files("demo_server").joinpath("data", FILE).read_text("utf-8")
    data = json.loads(raw)
    if not isinstance(data, dict) or data.get("simulated") is not True:
        raise ValueError("benchmark summary must be a simulated-data summary")
    return data
